'use strict';
/* La Cueva de Garra Negra, Nivel 1: Las Galerías (10/11, pedido del dueño: "que sean al menos 3 niveles y en uno
   encontremos a Urso, que pasen cosas en los niveles como trampas"; "referencias a una cueva de bestias, no picos";
   "me gusta que esté oscuro, que la iluminación sea por los hongos y esas cosas, para que se tenga que usar antorcha").
   Mapa nuevo del Taller (cueva_galerias, 1436×802, piezas ed_gl_*), de las tres capas de Nano Banana Pro del dueño.
   - Se entra por la boca de oso del Claro (arriba a la izquierda del Claro) y se llega abajo a la derecha, entre los
     colmillos; la salida de abajo vuelve al Claro.
   - OSCURA (ck_oscuridad.js): sin antorcha se ve muy poco; la luz es de la boca, de los rayos que bajan por las grietas
     del techo, de los hongos y del musgo. Dos braseros para prender con la antorcha (lugar seguro): en el último campamento
     de los cazadores orcos y en la sala del sumidero.
   - Bestias en la sombra: huargos y hombres lobo (y de noche, más). Como de noche en el pueblo, no se borran: se
     oscurecen y toman el color de la luz que tienen cerca (cálida con la antorcha o el brasero, verde y celeste al lado
     de los hongos); lejos de toda luz sólo se ven la silueta y los ojos rojos. Es una cueva: no hay día ni noche ni lluvia.
   - El cofre del botín (el del juego, se abre con T) queda detrás de la barricada de los orcos.
   - El sumidero (arriba a la izquierda) es la bajada al Nivel 2; todavía no está: T muestra el cartel.
   - Las trampas (cepos, derrumbe, fosa de estacas, barricada) están en ck_trampas_suelo.js.
   Va después de ck_oscuridad.js y ck_rompibles.js. Borrar su línea de index.html cierra la boca del Claro como antes. */
window.CK_GALERIAS_MINI = 'data:image/png;base64,';
(function () {
  if (typeof MainGameScene === 'undefined' || typeof INTERIOR_LAYOUTS === 'undefined') return;
  const D = window.EDITOR_DATA, ID = 'cueva_galerias', CLARO = 'claro_de_las_bestias';
  if (!D || !D.mapas || !D.mapas[ID] || !INTERIOR_LAYOUTS['ed_' + ID]) return;
  const Z = 'ed_' + ID + '.main', ZC = 'ed_' + CLARO + '.main';
  const LUGAR = { entrada: { x: 1190, y: 742 }, sumidero: { x: 217, y: 214 }, cofre: { x: 1122, y: 268 }, campamento: { x: 890, y: 665 } };
  const LLEGA = { cueva: { x: 1190, y: 772 }, claro: { x: 344, y: 254 } };   // (13/11) se llega al pie de la boca, entre los colmillos (al sur de la luz), y se entra caminando hacia la cueva
  const BRASEROS = [[968, 668], [306, 206]];
  // la penumbra de la cueva (fija: adentro no hay día ni noche); bestias y héroe se tiñen con la luz que tienen cerca
  const PENUMBRA = [30, 28, 46];
  // luces de la cueva (coordenadas del mapa): la boca, los rayos de las grietas del techo, hongos y musgo
  const LUCES = [
    { x: 1190, y: 650, c: [255, 214, 150], r: 175, f: 0.95 },        // la luz del día que entra por la boca
    { x: 1190, y: 585, c: [255, 225, 170], r: 90, f: 0.8 },
    { x: 205, y: 118, c: [205, 220, 255], r: 100, f: 0.72 },           // rayos de las grietas del techo
    { x: 690, y: 240, c: [205, 220, 255], r: 125, f: 0.72 },
    { x: 1032, y: 190, c: [205, 220, 255], r: 110, f: 0.72 },
    { x: 127, y: 76, c: [120, 255, 170], r: 72, f: 0.9, late: 1 },  // hongos
    { x: 318, y: 72, c: [110, 190, 255], r: 72, f: 0.9, late: 1 },
    { x: 132, y: 216, c: [150, 255, 120], r: 42, f: 0.45, late: 1 }, // musgo
    { x: 385, y: 162, c: [150, 255, 120], r: 36, f: 0.4, late: 1 },
    { x: 738, y: 168, c: [150, 255, 130], r: 50, f: 0.4, late: 1 },
    { x: 1135, y: 268, c: [150, 255, 130], r: 34, f: 0.35, late: 1 }
  ];
  // trampas (ck_trampas_suelo.js): los cinco cepos del pasillo de los cazadores, una fosa tapada a la salida de la sala de
  // las garras, el derrumbe del pasillo agrietado y la barricada de los orcos que cierra el botín
  const TRAMPAS = [
    { tipo: 'cepo', x: 685, y: 511 }, { tipo: 'cepo', x: 684, y: 555 }, { tipo: 'cepo', x: 681, y: 601 }, { tipo: 'cepo', x: 686, y: 644 }, { tipo: 'cepo', x: 752, y: 648 },
    { tipo: 'fosa', x: 832, y: 428 },
    { tipo: 'derrumbe', cajas: [[165, 382, 495, 422], [350, 236, 402, 386]] },
    { tipo: 'barricada', id: 'botin', x: 993, y: 430, golpes: 5, choque: [988, 296, 70, 130], rotaEn: [1014, 428] }
  ];
  window.CK_GALERIAS = { ID, Z, LUGAR, LUCES, BRASEROS, TRAMPAS };
  const P = MainGameScene.prototype;

  // ------------------------------------------------------------------ la boca del Claro se abre
  const LC = INTERIOR_LAYOUTS['ed_' + CLARO];
  if (LC) INTERIOR_LAYOUTS['ed_' + CLARO] = function (kit) {
    const r = LC.apply(this, arguments), a = kit.areas && kit.areas.main;
    if (a) {
      a.talkers = (a.talkers || []).filter(t => !(t.lines || []).some(l => /todavía no te animás a entrar/.test(l)));
      (a.exits = a.exits || []).push({ x: 322, y: 170, w: 44, h: 20, key: 'walk', to: 'gl_cueva', hint: '▲ La cueva de Garra Negra' });
    }
    return r;
  };
  const cofreFijo = S => {   // el cofre del juego va en el botín (detrás de la barricada), no en un rincón al azar
    const s = S && S.story; if (!s) return;
    s.flags = s.flags || {};
    const pos = (s.flags.cofres_pos3 = s.flags.cofres_pos3 || {});
    if (!pos[Z]) pos[Z] = [[LUGAR.cofre.x, LUGAR.cofre.y]];
  };
  const cambiar0 = P.switchInteriorArea;
  P.switchInteriorArea = function (nombre) {
    if ((nombre === 'gl_cueva' || nombre === 'gl_claro') && this._gameMode === 'campaign') {
      if (nombre === 'gl_cueva') cofreFijo(this);
      if (!this._doorTransition && this.ckEntrar) this.ckEntrar(nombre === 'gl_cueva' ? ID : CLARO, nombre === 'gl_cueva' ? LLEGA.cueva : LLEGA.claro);
      return;
    }
    return cambiar0.apply(this, arguments);
  };
  let registrado = false;
  const registrar = () => {
    if (registrado) return; registrado = true;
    try { const C = window.CK_PANTALLA_CARGA; if (C && C.REGION) C.REGION.unshift([/^cueva_galerias$/, 'La Cueva de Garra Negra']); } catch (e) {}
  };
  document.addEventListener('DOMContentLoaded', registrar);

  // ------------------------------------------------------------------ el mapa
  const L0 = INTERIOR_LAYOUTS['ed_' + ID];
  INTERIOR_LAYOUTS['ed_' + ID] = function (kit) {
    const r = L0.apply(this, arguments), a = kit.areas && kit.areas.main;
    if (a) {
      registrar();
      ['talkers', 'fx', 'colliders', 'exits'].forEach(k => (a[k] = a[k] || []));
      // ambiente propio (ElevenLabs): goteo con eco y viento hondo; si falta el mp3 suena el que tenga el mapa
      a.ambient = [['amb_cueva', 0.55]].concat((a.ambient || []).filter(s => s[0] !== 'amb_cueva').map(s => [s[0], s[1] * 0.4]));
      a.exits.push({ x: 1158, y: 802 - 16, w: 64, h: 16, key: 'walk', to: 'gl_claro', hint: '▼ Claro de las Bestias' });
      a.talkers.push({ x: LUGAR.sumidero.x, y: LUGAR.sumidero.y + 8, r: 40, lines: ['Un sumidero en el piso: raíces gruesas bajan a una oscuridad todavía más honda. De abajo sube olor a bestia… todavía no te animás a bajar'] });
      a.talkers.push({ x: 600, y: 356, r: 48, lines: ['El cráneo de un ciervo enorme, roído hasta el hueso. Lo que vive acá come bien'] });
      a.talkers.push({ x: 690, y: 400, r: 44, lines: ['Cuatro zarpazos hondos en el piso de roca. Ninguna espada deja una marca así'] });
      a.talkers.push({ x: 890, y: 650, r: 46, lines: ['El último campamento de los cazadores orcos: la carpa rota, el fuego frío, los escudos partidos por garras. No volvieron a salir'] });
      a.talkers.push({ x: 180, y: 600, r: 46, lines: ['El comedero de la manada: montañas de huesos y cueros arrancados. Mejor no quedarse mucho'] });
      a.talkers.push({ x: 1030, y: 260, r: 40, lines: ['Lo que las bestias arrastraron hasta acá: bolsas rotas, cajones arañados y monedas tiradas'] });
    }
    return r;
  };
  // ------------------------------------------------------------------ oscuridad y luces
  const instalar = () => {
    if (instalar.ok) return;
    if (window.CK_OSCURIDAD && !CK_OSCURIDAD.ZONAS[Z]) CK_OSCURIDAD.zona(Z, { braseros: BRASEROS, tinte: true, sala: PENUMBRA });
    if (window.CK_LUZ && CK_LUZ.fuente) {
      CK_LUZ.fuente((S, out) => {
        if (!S.currentInterior || !S.currentZoneKey || S.currentZoneKey() !== Z) return;
        const a = S.currentInterior.area, t = (S.time && S.time.now) || 0;
        LUCES.forEach((l, i) => {
          const f = l.late ? l.f * (0.82 + 0.18 * Math.sin(t / 900 + i * 1.7)) : l.f;   // los hongos y el musgo laten despacio
          out.push({ x: a.x + l.x, y: a.y + l.y, c: l.c, r: l.r, f });
        });
      });
    }
    if (window.CK_ROMPIBLES && CK_ROMPIBLES.COFRES && !CK_ROMPIBLES.COFRES[Z]) CK_ROMPIBLES.COFRES[Z] = 1;
    if (window.CK_TRAMPAS_SUELO && !CK_TRAMPAS_SUELO.ZONAS[Z]) CK_TRAMPAS_SUELO.zona(Z, TRAMPAS);
    instalar.ok = true;
  };
  instalar();
  document.addEventListener('DOMContentLoaded', instalar);
  if (typeof ZONE_ENEMIES !== 'undefined') {
    ZONE_ENEMIES[Z] = [['warg', 700, 380, 40], ['warg', 790, 420, 40], ['werewolf', 230, 610, 30], ['warg', 150, 560, 30],
      ['warg', 330, 400, 40], ['werewolf', 600, 330, 40, 'night'], ['warg', 1000, 400, 30, 'night']]
      .filter(e => ENEMY_TYPES[e[0]]);
  }
  // minimapa
  try {
    const MM = window.CK_MINIMAPA;
    if (MM && MM.Z) {
      MM.Z[Z] = { img: ID, esc: 4, w: 1436, h: 802, ext: 0, n: 'Las Galerías', g: 'Cueva de Garra Negra' };
      if (MM.L) {
        MM.L[Z] = [{ n: 'Sumidero (bajada)', x: LUGAR.sumidero.x, y: LUGAR.sumidero.y - 20, ic: 'estrella' },
          { n: 'Campamento de los cazadores', x: LUGAR.campamento.x, y: LUGAR.campamento.y - 30, ic: 'estrella' },
          { n: 'Claro de las Bestias', x: 1190, y: 796, ic: 'flecha', d: 's', va: ZC }];
        const C = MM.L[ZC];
        if (C && !C.some(l => l.va === Z)) C.push({ n: 'Cueva de Garra Negra', x: 344, y: 176, ic: 'flecha', d: 'n', va: Z });
      }
      if (MM.dibujo) MM.dibujo(ID, window.CK_GALERIAS_MINI);
    }
  } catch (e) {}
})();
